BEGIN;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','f10bd630-6e35-4513-a9b3-4908d1b00c3c',true);
DO $test$
DECLARE bank uuid; debt uuid; funded uuid; p jsonb; old jsonb; original jsonb; err text; n numeric;
BEGIN
 bank:=(public.open_financial_account(jsonb_build_object('request_id',gen_random_uuid(),'scope','PERSONAL','type','BANK','name','QA opening edit rollback','currency','SAR','opening_balance',1000,'opening_date','2026-10-01','fx_rate',1))->>'id')::uuid;
 original:=jsonb_build_object('action','CREATE','request_id',gen_random_uuid(),'party','QA opening creditor','description','Original opening','amount',150,'date','2026-10-14','due_date','2026-11-01','reference','');
 debt:=(public.personal_payable_command(original)->>'id')::uuid;
 old:=jsonb_build_object('amount',150,'date','2026-10-14','description','Original opening','due_date','2026-11-01','reference','');
 p:=jsonb_build_object('action','UPDATE','payable_id',debt,'amount',200,'date','2026-10-13','description','Corrected opening','due_date','2026-11-15','reference','OPEN-1','category','P_AP_PERSON','expected',old);
 PERFORM public.edit_personal_payable(p);
 IF NOT EXISTS(select 1 from public.personal_payables where id=debt and amount=200 and event_date='2026-10-13' and reference='OPEN-1') THEN RAISE EXCEPTION 'EDIT_NOT_SAVED';END IF;
 IF (public.personal_payable_command(original)->>'id')::uuid<>debt OR (select amount from public.personal_payables where id=debt)<>200 THEN RAISE EXCEPTION 'CREATE_REPLAY_CHANGED_EDIT';END IF;
 IF (select sum(remaining_value_base) from public.lots where asset_account_id=bank)<>1000 THEN RAISE EXCEPTION 'EDIT_MOVED_CASH';END IF;
 BEGIN PERFORM public.edit_personal_payable(p);err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PERSONAL_PAYABLE_EDIT_CONFLICT' THEN RAISE EXCEPTION 'STALE_EDIT_GUARD:%',err;END IF;
 old:=jsonb_build_object('amount',200,'date','2026-10-13','description','Corrected opening','due_date','2026-11-15','reference','OPEN-1');p:=jsonb_set(p,'{expected}',old);
 PERFORM set_config('request.jwt.claim.sub','8ec4c7f9-83b4-4307-9d5e-de7590fa121b',true);
 BEGIN PERFORM public.edit_personal_payable(p);err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PERSONAL_PAYABLE_ACCESS_DENIED' THEN RAISE EXCEPTION 'OWNER_GUARD:%',err;END IF;
 PERFORM set_config('request.jwt.claim.sub','f10bd630-6e35-4513-a9b3-4908d1b00c3c',true);
 PERFORM public.personal_payable_command(jsonb_build_object('action','PAY','request_id',gen_random_uuid(),'payable_id',debt,'account_id',bank,'amount',50,'date','2026-10-14','notes','QA partial payment'));
 BEGIN PERFORM public.edit_personal_payable(jsonb_set(p,'{amount}','220'));err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PERSONAL_PAYABLE_FINANCIAL_FIELDS_LOCKED' THEN RAISE EXCEPTION 'PAID_PRINCIPAL_GUARD:%',err;END IF;
 BEGIN PERFORM public.edit_personal_payable(jsonb_set(p,'{date}','"2026-10-12"'));err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PERSONAL_PAYABLE_FINANCIAL_FIELDS_LOCKED' THEN RAISE EXCEPTION 'PAID_DATE_GUARD:%',err;END IF;
 p:=jsonb_set(jsonb_set(p,'{description}','"Updated supporting description"'),'{reference}','"OPEN-2"');PERFORM public.edit_personal_payable(p);
 IF (select sum(remaining_value_base) from public.lots where asset_account_id=bank)<>950 OR (select sum(amount) from public.personal_payable_payments where payable_id=debt)<>50 THEN RAISE EXCEPTION 'METADATA_CHANGED_CASH_OR_PAYMENT';END IF;
 IF (select count(*) from public.audit_logs where entity_id=debt and entity_type='personal_payable' and action='EDIT')<>2 THEN RAISE EXCEPTION 'EDIT_AUDIT_MISSING';END IF;
 funded:=(public.personal_financing_command(jsonb_build_object('action','FUND','request_id',gen_random_uuid(),'kind','LOAN','side','PAYABLE','party','QA funded creditor','description','Funded amount','reference','FUND-1','amount',100,'date','2026-10-15','due_date','2026-11-15','account_id',bank))->>'id')::uuid;
 select jsonb_build_object('amount',amount,'date',event_date,'description',description,'due_date',due_date,'reference',reference),id into old,debt from public.personal_payables where id=(select payable_id from public.personal_financings where id=funded);
 p:=old||jsonb_build_object('action','UPDATE','payable_id',debt,'category','P_AP_LOAN','expected',old);
 BEGIN PERFORM public.edit_personal_payable(jsonb_set(p,'{amount}','110'));err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PERSONAL_PAYABLE_FINANCIAL_FIELDS_LOCKED' THEN RAISE EXCEPTION 'FUNDED_AMOUNT_GUARD:%',err;END IF;
 BEGIN PERFORM public.edit_personal_payable(jsonb_set(p,'{due_date}','"2026-12-15"'));err:='NOT_BLOCKED';EXCEPTION WHEN OTHERS THEN err:=SQLERRM;END;
 IF err<>'PERSONAL_FINANCING_USE_SOURCE' THEN RAISE EXCEPTION 'FUNDED_DUE_GUARD:%',err;END IF;
 PERFORM set_config('qa.personal_payable_edit.result','{"edit_saved":true,"create_replay_safe":true,"no_cash_on_edit":true,"stale_edit_blocked":true,"owner_guard":true,"paid_principal_and_date_protected":true,"metadata_edit_after_payment":true,"funding_source_protected":true,"audit":true,"rollback":true}',true);
END $test$;
SELECT current_setting('qa.personal_payable_edit.result')::jsonb result;
ROLLBACK;
